'use strict';
const assert = require('node:assert');
const { PreferenceState } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['PreferenceState']);
const initial = { remoteAllowed: false };
const state = new PreferenceState(initial);
initial.remoteAllowed = true;
assert.deepStrictEqual(state.snapshot(), { remoteAllowed: false });

const first = state.snapshot();
const second = state.snapshot();
assert.notStrictEqual(first, second);
assert.ok(Object.isFrozen(first));
assert.throws(() => { first.remoteAllowed = true; }, TypeError);
assert.deepStrictEqual(state.snapshot(), { remoteAllowed: false });

const event = { detail: { value: true } };
const applied = state.apply(event);
assert.deepStrictEqual(applied, { remoteAllowed: true });
assert.ok(Object.isFrozen(applied));
event.detail.value = false;
assert.deepStrictEqual(state.snapshot(), { remoteAllowed: true });
assert.deepStrictEqual(state.apply({ detail: { value: false } }), { remoteAllowed: false });

for (const bad of [undefined, null, {}, { remoteAllowed: 1 }, { remoteAllowed: true, extra: 1 },
  Object.assign(Object.create({ inherited: true }), { remoteAllowed: true })]) {
  assert.throws(() => new PreferenceState(bad), TypeError);
}

for (const bad of [undefined, null, {}, { detail: { value: true }, extra: 1 }, { detail: null },
  { detail: {} }, { detail: { value: 1 } }, { detail: { value: true, extra: 1 } },
  Object.assign(Object.create({ inherited: true }), { detail: { value: true } }),
  { detail: Object.assign(Object.create({ inherited: true }), { value: true }) }]) {
  assert.throws(() => state.apply(bad), TypeError);
  assert.deepStrictEqual(state.snapshot(), { remoteAllowed: false });
}

